490:         private void EnqueueUnreliable(NetPacket packet)
491:         {
492:             if (IsPriorityUnreliable(packet))
493:             {
494:                 EnqueuePriorityUnreliable(packet);
495:                 return;
496:             }
497: 
498:             _unreliableChannel.Enqueue(packet);
499: 
500:             // Counted unconditionally so the depth stays honest even while unbounded — the drain
501:             // decrements either way, and skipping the increment here would drive it negative and
502:             // silently disable the bound if the limit were ever raised at runtime.
503:             int depth = Interlocked.Increment(ref _unreliableCount);
504: 
505:             // Resolved from population and box size on the last join/leave, not the raw config
506:             // field — see NetManager.RecomputePoolCap.
507:             int limit = NetManager.EffectiveUnreliableQueuePerPeer;
508:             if (limit <= 0 || depth <= limit) return;
509: 
510:             // Over budget: the producer is outrunning the send loop. Drop from the front until we
511:             // are back inside it.
512:             //
513:             // This queue used to be unbounded, which turned a CPU overload into an out-of-memory:
514:             // at 2000 players the send loop enqueued faster than the logic pass could drain, and
515:             // the backlog reached ~40 GB before every peer timed out. Bounding it converts that
516:             // into what it always should have been — dropped frames on a server that is behind.
517:             //
518:             // Oldest-first, because these are position updates: the newest frame supersedes
519:             // everything queued behind it, so a stale one is exactly what you want to lose.
520:             while (Volatile.Read(ref _unreliableCount) > limit && _unreliableChannel.TryDequeue(out var stale))
521:             {
522:                 Interlocked.Decrement(ref _unreliableCount);
523:                 NetManager.NoteUnreliableDropped();
524:                 NetManager.PoolRecycle(stale);
525:             }
526:         }
